'use strict';

// MAIN //

/**
* Converts a normalized RFC 3339 timestamp to a portable filename component.
*
* @param {string} timestamp - normalized timestamp
* @returns {string} filename timestamp
*/
function filenameTimestamp( timestamp ) {
	return timestamp.replaceAll( '-', '_' ).replaceAll( ':', '_' );
}


// EXPORTS //

module.exports = filenameTimestamp;
